sw_expect($service->applyRequirementChangeProposal($proposal, $requirement, 'org-a', 9) && (($sources->requirements[$requirement]['requirement_text'] ?? '') === 'Requires documentation, signed order, and recent usage report.') && (($service->requirementChangeProposals($requirement, 'org-a')[0]['proposal_status'] ?? '') === 'applied') && (($service->requirementDetailWorkspace($requirement, 'org-a')['revisions'][0]['revision_type'] ?? '') === 'change_proposal_applied'), 'applied requirement change proposals mutate the requirement through the service and append immutable revision history');
