try { $service->applyRequirementChangeProposal($staleProposal, $requirement, 'org-a', 9); throw new RuntimeException('Stale no-op proposal was applied.'); } catch (InvalidArgumentException) { sw_expect(true, 'stale no-op requirement change proposals cannot be applied'); }
