try { $service->clearSourceImpactReview($requirement, 'org-a', 9, 'Reviewed source while draft proposal remains.'); throw new RuntimeException('Draft proposal did not block source review closeout.'); } catch (InvalidArgumentException) { sw_expect(true, 'source review closeout is blocked while draft requirement change proposals remain'); }
$service->rejectRequirementChangeProposal($blockingProposal, $requirement, 'org-a', 9, 'Rejected blocking draft before closeout.');
sw_expect($service->clearSourceImpactReview($requirement, 'org-a', 9, 'Reviewed updated source; requirement remains accurate.') && $service->requirements('org-a', ['source_review_status'=>'needs_source_review']) === [] && ($sources->requirements[$requirement]['source_review_reason'] ?? '') !== '', 'source impact review queue can be cleared after human requirement review with a retained note');
